/**
 * GitHub Actions workflows generated by `violet cicd setup`.
 *
 * Two paths work today:
 * - File-driven (validate, release): the repo keeps DTCG node files and the
 *   workflow runs `violet --from <dir>` with the project's installed
 *   @lushly-dev/violet-cli. No database and no API key.
 * - Hosted fetch (sync): curl against a Violet deployment's
 *   `/api/v1/export/:nodeId/<format>` and open a pull request with the result.
 *   No CLI install.
 */

import { HOSTED_EXPORT_FORMATS } from '@lushly-dev/violet-afd';

export const CICD_TEMPLATES = ['sync', 'validate', 'release'] as const;
export type CicdTemplate = (typeof CICD_TEMPLATES)[number];

export interface CicdTemplateOptions {
	/** Node to validate, export or fetch */
	node: string;
	/** Directory holding the DTCG node files (file-driven templates) */
	tokensDir: string;
}

/** The package the file-driven workflows run. Never `npx violet`: that is an unrelated npm package. */
export const CLI_PACKAGE = '@lushly-dev/violet-cli';

/** Shown wherever the generated files or CLI output say how to install the CLI */
export const CLI_NOT_PUBLISHED_NOTE = `${CLI_PACKAGE} is not on npm yet (lushly-dev/violet#30, #42). Until its first release, install it from a local build or workspace link.`;

/** Same pins as Violet's own .github/workflows */
export const ACTION_PINS = {
	checkout: 'actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1',
	setupNode: 'actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0',
} as const;

export const NODE_VERSION = '24';

/** Formats the hosted API serves at /api/v1/export/:nodeId/<format>, shared with the API */
export { HOSTED_EXPORT_FORMATS };

/** Formats `violet cicd export` writes in the release workflow */
export const RELEASE_FORMATS = ['json', 'css', 'scss', 'typescript', 'swift', 'kotlin', 'dart'];

/** Node IDs and paths are written into the YAML unquoted, so keep them to safe characters */
export const SAFE_NODE_ID = /^[A-Za-z0-9._-]+$/;
export const SAFE_TOKENS_DIR = /^[A-Za-z0-9._-]+(\/[A-Za-z0-9._-]+)*$/;

export function isCicdTemplate(name: string): name is CicdTemplate {
	return (CICD_TEMPLATES as readonly string[]).includes(name);
}

export function workflowFilename(template: CicdTemplate): string {
	return `tokens-${template}.yml`;
}

export function getWorkflowTemplate(template: CicdTemplate, options: CicdTemplateOptions): string {
	switch (template) {
		case 'sync':
			return syncWorkflow(options);
		case 'validate':
			return validateWorkflow(options);
		case 'release':
			return releaseWorkflow(options);
	}
}

/** Steps shared by the file-driven workflows: checkout, Node, npm ci, and a clear error when the CLI is missing */
function cliSetupSteps(): string {
	return `      - name: Checkout
        uses: ${ACTION_PINS.checkout}
        with:
          persist-credentials: false

      - name: Setup Node.js
        uses: ${ACTION_PINS.setupNode}
        with:
          node-version: '${NODE_VERSION}'
          cache: npm

      - name: Install dependencies
        run: npm ci

      - name: Check the Violet CLI
        # --no runs the project's ${CLI_PACKAGE} and never downloads the unrelated npm package named violet.
        # -- stops npx reading violet's flags (--from, --json, --version) as its own.
        run: |
          if ! npx --no -- violet --version > /dev/null 2>&1; then
            echo "::error::${CLI_PACKAGE} is not installed. Add it with: npm install --save-dev ${CLI_PACKAGE}"
            exit 1
          fi`;
}

function cliHeader(description: string): string {
	return `# Generated by \`violet cicd setup\` (${CLI_PACKAGE}).
# ${description}
#
# Needs ${CLI_PACKAGE} in devDependencies (npm install --save-dev ${CLI_PACKAGE}).
# ${CLI_NOT_PUBLISHED_NOTE}
# Until then the "Check the Violet CLI" step fails.
#
# Token files: one DTCG file per node in the tokens directory, each naming its parent under
# $extensions["dev.lushly.violet"]. Run the same steps locally with:
#   npx --no -- violet --from <tokens dir> cicd validate --node <node>`;
}

function validateWorkflow({ node, tokensDir }: CicdTemplateOptions): string {
	return `${cliHeader('Validates the DTCG token files on pull requests: builds the node tree with --from (no database), checks constraints, and exports as a build check.')}
name: Validate Design Tokens

on:
  pull_request:
    paths:
      - '${tokensDir}/**'
      - '.github/workflows/tokens-validate.yml'
  workflow_dispatch:

permissions:
  contents: read

env:
  VIOLET_TOKENS_DIR: ${tokensDir}
  # Node ID: a file name in the tokens directory without .tokens.json, or its $extensions node
  VIOLET_NODE: ${node}

jobs:
  validate:
    runs-on: ubuntu-latest

    steps:
${cliSetupSteps()}

      - name: Validate tokens
        run: npx --no -- violet --from "$VIOLET_TOKENS_DIR" cicd validate --node "$VIOLET_NODE"

      - name: Export tokens
        run: npx --no -- violet --from "$VIOLET_TOKENS_DIR" cicd export --node "$VIOLET_NODE" --formats json,css --output "$RUNNER_TEMP/violet-tokens"
`;
}

function releaseWorkflow({ node, tokensDir }: CicdTemplateOptions): string {
	return `${cliHeader('On a tokens-v* tag, exports the DTCG token files with --from (no database) and attaches them to a GitHub release.')}
name: Release Design Tokens

on:
  push:
    tags:
      - 'tokens-v*'

permissions:
  contents: write

env:
  VIOLET_TOKENS_DIR: ${tokensDir}
  # Node ID: a file name in the tokens directory without .tokens.json, or its $extensions node
  VIOLET_NODE: ${node}

jobs:
  release:
    runs-on: ubuntu-latest

    steps:
${cliSetupSteps()}

      - name: Validate tokens
        run: npx --no -- violet --from "$VIOLET_TOKENS_DIR" cicd validate --node "$VIOLET_NODE"

      - name: Export all formats
        run: npx --no -- violet --from "$VIOLET_TOKENS_DIR" cicd export --node "$VIOLET_NODE" --formats ${RELEASE_FORMATS.join(',')} --output violet-dist

      - name: Create release
        env:
          GH_TOKEN: \${{ github.token }}
        run: gh release create "$GITHUB_REF_NAME" violet-dist/* --title "Design tokens $GITHUB_REF_NAME" --generate-notes
`;
}

function syncWorkflow({ node }: CicdTemplateOptions): string {
	return `# Generated by \`violet cicd setup\` (${CLI_PACKAGE}).
# Fetches exported tokens from a hosted Violet API and opens a pull request when they change.
# It does not install the Violet CLI.
#
# Needs, under Settings > Secrets and variables > Actions:
#   - variable VIOLET_API_URL: your Violet deployment, for example https://violet.example.com (required, no default)
#   - secret VIOLET_API_KEY: a hosted API key with the export:read scope
# and "Allow GitHub Actions to create and approve pull requests" under Settings > Actions > General.
# Pull requests opened with the default GITHUB_TOKEN do not trigger other workflows.
name: Sync Design Tokens

on:
  workflow_dispatch:
    inputs:
      node_id:
        description: Node ID to export
        required: true
        default: ${node}
  repository_dispatch:
    types: [violet_tokens_updated]

permissions:
  contents: write
  pull-requests: write

concurrency:
  group: \${{ github.workflow }}
  cancel-in-progress: false

env:
  # Formats the API serves: ${HOSTED_EXPORT_FORMATS.join(' ')}
  VIOLET_FORMATS: css json
  VIOLET_OUTPUT_DIR: src/tokens
  NODE_ID: \${{ github.event.client_payload.node_id || inputs.node_id || '${node}' }}

jobs:
  sync:
    runs-on: ubuntu-latest

    steps:
      - name: Checkout
        uses: ${ACTION_PINS.checkout}

      - name: Fetch tokens from Violet
        env:
          VIOLET_API_URL: \${{ vars.VIOLET_API_URL }}
          VIOLET_API_KEY: \${{ secrets.VIOLET_API_KEY }}
        run: |
          if [ -z "$VIOLET_API_URL" ]; then
            echo "::error::Set the VIOLET_API_URL repository variable to your Violet deployment URL"
            exit 1
          fi
          if [ -z "$VIOLET_API_KEY" ]; then
            echo "::error::Set the VIOLET_API_KEY repository secret to a key with the export:read scope"
            exit 1
          fi
          if ! [[ "$NODE_ID" =~ ^[A-Za-z0-9._-]+$ ]]; then
            echo "::error::Invalid node ID: $NODE_ID"
            exit 1
          fi
          mkdir -p "$VIOLET_OUTPUT_DIR"
          response="$RUNNER_TEMP/violet-export.json"
          for format in $VIOLET_FORMATS; do
            case "$format" in
              typescript) ext=ts ;;
              kotlin) ext=kt ;;
              *) ext="$format" ;;
            esac
            # --fail exits non-zero on an HTTP error instead of saving the error body as tokens
            curl --fail --silent --show-error --retry 3 \\
              -H "X-API-Key: $VIOLET_API_KEY" \\
              "\${VIOLET_API_URL%/}/api/v1/export/$NODE_ID/$format" \\
              -o "$response"
            jq --exit-status --raw-output '.data.content' "$response" > "$VIOLET_OUTPUT_DIR/tokens.$ext"
          done

      - name: Open a pull request
        env:
          GH_TOKEN: \${{ github.token }}
        run: |
          git add -- "$VIOLET_OUTPUT_DIR"
          if git diff --cached --quiet; then
            echo "Tokens are up to date"
            exit 0
          fi
          branch="violet/tokens-$NODE_ID"
          title="chore(tokens): sync $NODE_ID from Violet"
          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git switch -c "$branch"
          git commit -m "$title"
          git push --force origin "$branch"
          if [ "$(gh pr list --head "$branch" --state open --json number --jq length)" = "0" ]; then
            gh pr create --head "$branch" --title "$title" \\
              --body "Tokens for \\\`$NODE_ID\\\` exported from Violet by $GITHUB_SERVER_URL/$GITHUB_REPOSITORY/actions/runs/$GITHUB_RUN_ID."
          fi
`;
}
